  { id: 'ama', label: 'ΑΜΑ (registry number)', short: 'ΑΜΑ', type: 'ama' },
  { id: 'liability_insurance', label: 'Liability insurance', short: 'Insurance' },
  { id: 'disinfection', label: 'Disinfection / rodent control', short: 'Pest control' },
  { id: 'smoke_detector', label: 'Fire alarm / smoke detector', short: 'Smoke alarm' },
