// ── Owner contact ───────────────────────────────────────────────
// Emails are owned by Configuration (ownerEmail / 2 / 3) and only shown here.
// The phone number is new and lives on the apartment beside them, so the rest
// of the app can use it too. Saved on blur; no re-render, so typing is safe.
function _ownerEmails(a) {
  return [a && a.ownerEmail, a && a.ownerEmail2, a && a.ownerEmail3]
    .map(function (e) { return String(e || '').trim(); }).filter(Boolean);
}
function _telHref(v) { return String(v || '').replace(/[^+0-9]/g, ''); }
window.pinfoOwnerPhone = function (aptId, v) {
  const a = (S.apts || []).filter(function (x) { return x.id === aptId; })[0];
  if (!a) return;
  const nv = String(v || '').trim();
  if (nv === String(a.ownerPhone || '')) return;
  a.ownerPhone = nv; save();
  if (typeof logChange === 'function') logChange('Property Info', 'Owner phone', a.name + ' → ' + (nv || '(cleared)'));
  if (typeof toast === 'function') toast(nv ? 'Phone saved for ' + a.name + '.' : 'Phone cleared for ' + a.name + '.', 'ok');
};
function _ownerBlockHtml(a) {
  const es = _ownerEmails(a);
  return '<div class="card" style="margin-top:14px">' +
    '<div style="font-size:14px;font-weight:700;color:var(--tx)">Owner contact</div>' +
    '<div style="font-size:11px;color:var(--tx3);margin:2px 0 10px">Emails come from Configuration - edit them there. The phone number is saved as soon as you leave the field.</div>' +
    '<div style="display:flex;flex-wrap:wrap;gap:26px;align-items:flex-start">' +
    '<div style="min-width:240px"><div style="font-size:11px;text-transform:uppercase;letter-spacing:.04em;color:var(--tx3);margin-bottom:4px">' +
    (a.ownerName ? _esc(a.ownerName) + ' · ' : '') + 'Email' + (es.length === 1 ? '' : 's') + '</div>' +
    (es.length ? es.map(function (e) { return '<div style="font-size:13px;padding:1px 0"><a href="mailto:' + _esc(e) + '" style="color:#C9A84C;text-decoration:none">' + _esc(e) + '</a></div>'; }).join('')
               : '<div style="font-size:12px;color:var(--tx-err)">No owner email set in Configuration</div>') +
    '</div>' +
    '<div><div style="font-size:11px;text-transform:uppercase;letter-spacing:.04em;color:var(--tx3);margin-bottom:4px">Phone</div>' +
    '<input type="tel" value="' + _esc(a.ownerPhone || '') + '" placeholder="+30 69…" onchange="pinfoOwnerPhone(\'' + _esc(a.id) + '\',this.value)" style="' + IN + ';width:200px">' +
    (a.ownerPhone ? '<a href="tel:' + _esc(_telHref(a.ownerPhone)) + '" style="color:#C9A84C;font-size:12px;text-decoration:none;margin-left:8px">call</a>' : '') +
    '</div></div></div>';
}
function _ownerTableHtml(apts) {
  const missing = apts.filter(function (a) { return !_ownerEmails(a).length; }).length;
  const noPhone = apts.filter(function (a) { return !String(a.ownerPhone || '').trim(); }).length;
  const rows = apts.map(function (a) {
    const es = _ownerEmails(a);
    return '<tr style="border-bottom:1px solid var(--bdr)">' +
      '<td style="padding:5px 8px;font-size:12px;white-space:nowrap">' + _esc(a.name) + '</td>' +
      '<td style="padding:5px 8px;font-size:11px;color:var(--tx3);white-space:nowrap">' + _esc(a.ownerName || '') + '</td>' +
      '<td style="padding:5px 8px;font-size:12px">' + (es.length
        ? es.map(function (e) { return '<a href="mailto:' + _esc(e) + '" style="color:#C9A84C;text-decoration:none">' + _esc(e) + '</a>'; }).join('<span style="color:var(--tx3)"> · </span>')
        : '<span style="color:var(--tx-err)">no email</span>') + '</td>' +
      '<td style="padding:4px 8px;white-space:nowrap"><input type="tel" value="' + _esc(a.ownerPhone || '') + '" placeholder="+30 …" onchange="pinfoOwnerPhone(\'' + _esc(a.id) + '\',this.value)" style="' + IN + ';width:160px;font-size:12px;padding:4px 7px">' +
      (a.ownerPhone ? '<a href="tel:' + _esc(_telHref(a.ownerPhone)) + '" style="color:#C9A84C;font-size:11px;text-decoration:none;margin-left:6px">call</a>' : '') + '</td></tr>';
  }).join('');
  return '<div class="card" style="margin-top:14px;padding:0;overflow:auto">' +
    '<div style="padding:12px 14px 8px;display:flex;align-items:baseline;gap:10px;flex-wrap:wrap">' +
    '<div style="font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:.05em;color:var(--tx2)">Owner contacts</div>' +
    '<div style="font-size:11px;color:var(--tx3)">emails from Configuration · phone editable here' +
    (missing ? ' · <span style="color:var(--tx-err)">' + missing + ' without an email</span>' : '') +
    (noPhone ? ' · <span style="color:var(--tx-warn)">' + noPhone + ' without a phone</span>' : '') + '</div></div>' +
    '<table style="border-collapse:collapse;width:100%;min-width:760px">' +
    '<tr><th style="text-align:left;padding:6px 8px;font-size:10px;color:var(--tx3);border-bottom:1px solid var(--bdr2)">Apartment</th>' +
    '<th style="text-align:left;padding:6px 8px;font-size:10px;color:var(--tx3);border-bottom:1px solid var(--bdr2)">Owner</th>' +
    '<th style="text-align:left;padding:6px 8px;font-size:10px;color:var(--tx3);border-bottom:1px solid var(--bdr2)">Email(s)</th>' +
    '<th style="text-align:left;padding:6px 8px;font-size:10px;color:var(--tx3);border-bottom:1px solid var(--bdr2)">Phone</th></tr>' +
    rows + '</table></div>';
}
window.pinfoMatrixGo = function (id) { pinfoSelectRental(id); };
